class Solution { public int sumSubarrayMins(int[] arr){long mod=1000000007L,answer=0;Deque<Integer> stack=new ArrayDeque<>();for(int i=0;i<=arr.length;i++){while(!stack.isEmpty()&&(i==arr.length||arr[stack.peek()]>=arr[i])){int middle=stack.pop(),left=stack.isEmpty()?-1:stack.peek();answer=(answer+(long)arr[middle]*(middle-left)*(i-middle))%mod;}if(i<arr.length)stack.push(i);}return(int)answer;} }
